cases_p1 {
    columns       { time : time, cases_p1 : count }
    covers        = closing_at(time, 7 'days)
    projected     = incidence(recovery_p1)
    emit_schedule = every 7 'days
    cases_p1      ~ neg_binomial(mean = rho * projected, r = k)
  }

